             return fract(sin(u)*279791.12345+seed*0.9);
         }
         float noise(float u, float amzLocal_size, float seed)
         {
             float zoom = u * amzLocal_size;
             float index = floor(zoom);
             float progress = fract(zoom);
             float value = mix(random(index, seed), random(index + 1.0, seed), progress);
             return value;
         }
